@DomainOrder.free_omega_sem_le_upper
     : forall (MN : Type -> Type) (R : reals.Real.type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (NO : @Omega.SemanticOmega MN NI)
         (native : forall X : Type, MN X -> Expectation.OmegaVal R X),
       (forall (X : Type) (mu : MN X) (P : X -> Prop),
        @Measure.sem_ae MN NI X mu P -> @Countable.oval_ae R X (native X mu) P) ->
       (forall (X : Type) (x : X),
        @Expectation.oval_eq R X (native X (@Measure.sem_ret MN NI X x))
          (@Expectation.oval_ret R X x)) ->
       (forall X : Type,
        @Expectation.oval_eq R X (native X (@Omega.sem_zero MN NI NO X))
          (@Expectation.oval_bottom R X)) ->
       (forall (X Y : Type) (mu : MN X) (k : X -> MN Y),
        @Expectation.oval_eq R Y (native Y (@Measure.sem_bind MN NI X Y mu k))
          (@Expectation.oval_bind R X Y (native X mu) (fun x : X => native Y (k x)))) ->
       (forall (X Y : Type) (T : X -> Y -> Prop) (mu : MN X) (nu : MN Y)
          (f : X -> reals.Real.sort R) (g : Y -> reals.Real.sort R),
        @Measure.sem_lift MN NI X Y T mu nu ->
        @Expectation.oval_test R X f ->
        @Expectation.oval_test R Y g ->
        (forall (x : X) (y : Y),
         T x y ->
         is_true
           (@order.Order.le ssrnum.ring_display (reals.Real.Exports.reals_Real__to__Order_POrder R)
              (f x) (g y))) ->
        is_true
          (@order.Order.le ssrnum.ring_display (reals.Real.Exports.reals_Real__to__Order_POrder R)
             (@Expectation.oval_eval R X (native X mu) f)
             (@Expectation.oval_eval R Y (native Y nu) g))) ->
       (forall (X : Type) (c : nat -> MN X) (out : MN X),
        (forall (n : nat) (f : X -> reals.Real.sort R),
         @Expectation.oval_test R X f ->
         is_true
           (@order.Order.le ssrnum.ring_display (reals.Real.Exports.reals_Real__to__Order_POrder R)
              (@Expectation.oval_eval R X (native X (c n)) f)
              (@Expectation.oval_eval R X (native X (c (S n))) f))) ->
        @Omega.sem_lub MN NI NO X c out ->
        forall f : X -> reals.Real.sort R,
        @Expectation.oval_test R X f ->
        @Expectation.oval_sup R (fun n : nat => @Expectation.oval_eval R X (native X (c n)) f) =
        @Expectation.oval_eval R X (native X out) f) ->
       forall (A : Type) (t u : Definition.FreeOmega MN A),
       @DomainOrder.free_omega_sem_le MN NI NO A t u ->
       forall f : A -> reals.Real.sort R,
       @Expectation.oval_test R A f ->
       is_true
         (@order.Order.le ssrnum.ring_display (reals.Real.Exports.reals_Real__to__Order_POrder R)
            (@Model.free_omega_model_upper MN R native A t f)
            (@Model.free_omega_model_upper MN R native A u f))

